/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from 'playwright'
import { expect } from '@playwright/test'
import { instant } from '@next/playwright'

const browser = await chromium.launch({ headless: true })
const origin = 'http://localhost:3000'
const cases = [
  { category: 'featured', heading: 'Featured products', products: ['Desk Lamp', 'Wool Blanket'] },
  { category: 'sale', heading: 'Products on sale', products: ['Canvas Tote', 'Travel Mug'] },
]

try {
  for (const { category, heading, products } of cases) {
    const page = await browser.newPage()
    const href = "'`/catalog?category=${category}`
    const prefetched = page.waitForResponse((response) => {
      const url = new URL(response.url())
      return url.pathname === '"'/catalog'
        && url.searchParams.get('category') === category
        && response.request().headers()['next-router-prefetch'] === '2'
        && response.ok()
    })
    await page.goto(origin)
    await prefetched
    await instant(page, async () => {
      await page.locator("'`a[href="${href}"]`).click()
      await page.waitForURL((url) => url.pathname === '"'/catalog' && url.searchParams.get('category') === category)
      await expect(page.getByRole('heading', { name: heading })).toBeVisible()
      for (const product of products) {
        await expect(page.getByText(product, { exact: true })).toBeVisible()
      }
      await expect(page.getByText('Loading category...')).toHaveCount(0)
    })
    console.log("'`PASS: ${category} content was present during instant navigation`)
    await page.close()
  }
} finally {
  await browser.close()
}
EOF'

